import Foundation
import Observation

@Observable
final class SettingsStore {
    var prefersMetricUnits: Bool {
        didSet { defaults.set(prefersMetricUnits, forKey: Keys.metric) }
    }

    @ObservationIgnored private let defaults: UserDefaults

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.prefersMetricUnits = defaults.bool(forKey: Keys.metric)
    }

    private enum Keys {
        static let metric = "settings.prefersMetricUnits"
    }
}
